with p as (select id from liq_proveedores where nombre='First Abu Dhabi Bank')
update liq_proveedores set email_patron=null, email_patron_fuente='no se halló patrón corroborado por una dirección publicada · confianza: n/a',
 canales_publicos='[{"canal": "Sitio oficial / newsroom (In the media)", "valor": "https://www.bankfab.com/en-ae/about-fab/group/in-the-media/completes-tokenized-deposit-milestone-with-citi-swift-ledger", "fuente": "https://www.bankfab.com/en-ae/about-fab/group/in-the-media/completes-tokenized-deposit-milestone-with-citi-swift-ledger"}, {"canal": "Investor Relations (buzón institucional)", "valor": "ir@bankfab.com", "fuente": "https://www.bankfab.com/en-ae/about-fab/investor-relations"}, {"canal": "Global Markets inbox (página de contacto KSA y página Corporate & Investment Banking KSA)", "valor": "gmbm@bankfab.com", "fuente": "https://www.bankfab.com/en-sa/contact-us"}, {"canal": "Global Transaction Banking inbox (página de contacto KSA)", "valor": "tbchannel.support@bankfab.com", "fuente": "https://www.bankfab.com/en-sa/contact-us"}, {"canal": "Formulario de contacto web", "valor": "https://www.bankfab.com/v1/en-sa/contact-us", "fuente": "https://www.bankfab.com/v1/en-sa/contact-us"}, {"canal": "LinkedIn (página de empresa)", "valor": null, "fuente": "https://bankfab.com/en-gb"}, {"canal": "X/Twitter", "valor": null, "fuente": "https://bankfab.com/en-gb"}, {"canal": "Buzón genérico: Buzón institucional FAB (Global Markets / Investor Relations) — Inbox genérico", "valor": "gmbm@bankfab.com", "fuente": "https://www.bankfab.com/en-sa/contact-us"}]'::jsonb, ruta_recomendada='1) Enviar el correo a Futoon AlMazrouei (Group Head of Personal, Wealth, Business Banking and Privileged Client Group; confirmada en el cargo en 2026 y ejecutiva de FAB citada en la aprobación del stablecoin DDSC) vía LinkedIn/InMail, ya que no hay patrón de email corporativo verificado; ángulo: distribución de productos tokenizados a clientes wealth/privileged y uso de DDSC como settlement. 2) En paralelo, contactar a Azzam Anani (responsable interino de Global Markets desde ene-2025 tras la renuncia de Sameh Al Qubaisi; confirmar en LinkedIn que sigue al frente antes de escribir) para el ángulo institucional: colateral tokenizado (Libre Capital) y bono digital (HSBC Orion / Euroclear D-FMI). 3) Intro cálida: Libre Capital (socio de FAB en préstamos con colateral tokenizado), Kaleido (socio tecnológico de FAB en depósitos tokenizados, contacto Juan Silva en LinkedIn), Kinexys/J.P. Morgan, HSBC Orion, Euroclear D-FMI o ADI Foundation/Sirius (DDSC). 4) Si no hay respuesta en 10 días, escribir al buzón de Global Markets gmbm@bankfab.com (publicado en la página de contacto KSA y en Corporate & Investment Banking KSA) pidiendo redirección al equipo de activos digitales, y en paralelo a ir@bankfab.com. 5) Fallback: formulario web de FAB y mensaje a la Group CEO Hana Al Rostamani vía su oficina solo con una referencia de tercero.',
 decisor=coalesce('Azzam Anani — Head of Global Markets (interino desde ene-2025)',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Consorcio UAE (con IHC y Sirius) para la stablecoin DDSC ligada al dírham para liquidación de tokenización en ADGM; pilotos de depósitos tokenizados con Kinexys.'||E'\n'||'Investigación automática 2026-10-19 (lote EXPLORE 2 del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Buzones genéricos movidos a canales_publicos: Buzón institucional FAB (Global Markets / Investor Relations). Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='First Abu Dhabi Bank'), v.* from (values
('Futoon Hamdan AlMazrouei','Group Head of Personal, Wealth, Business Banking and Privileged Client Group','Banca de personas, wealth, empresas y privileged clients (sponsor de DDSC en FAB)','Abu Dhabi, UAE',null,null,'desconocido','decisor',1,'Ejecutiva de FAB citada en la aprobación del stablecoin DDSC por el CBUAE (feb-2026); decide la distribución de DDSC y productos digitales a clientes FAB. Es la contacto mejor sustentada actualmente en el cargo (2026).','https://www.bankfab.com/-/media/fabgroup/home/about-fab/group/senior-management/bios/fab-senior-management-biographies.pdf','Verificación: confirmada en el cargo en 2026 (perfil de liderazgo actualizado jun-2026 en theofficialboard.com; biografías oficiales de la alta dirección de FAB; Finance Middle East sobre la reorganización del comité ejecutivo: https://www.financemiddleeast.com/banking-and-insurance/first-abu-dhabi-bank-reshuffles-executive-committee-amid-leadership-changes/). Cargo ajustado a la denominación publicada. Promovida a prioridad 1 porque Sameh Al Qubaisi dejó FAB en ene-2025. Cita en la aprobación del DDSC: https://www.theasianbanker.com/press-releases/cbuae-approves-uae-dirham-backed-stablecoin-ddsc-for-operational-launch. Perfil retail/wealth, no BD institucional; útil si el ángulo es distribución a clientes wealth o uso de DDSC como settlement. Sin email verificado; no se encontró patrón corporativo.'),
('Azzam Anani','Head of Global Markets (interino desde ene-2025)','Global Markets (trading, ventas, productos; colateral tokenizado, bono digital)','Abu Dhabi, UAE',null,null,'desconocido','dueno_programa',2,'Cubre interinamente la jefatura de Global Markets tras la renuncia de Sameh Al Qubaisi (ene-2025); Global Markets es el área que ejecutó el préstamo con colateral tokenizado (Libre Capital) y el bono digital verde en Euroclear D-FMI, el área natural para evaluar cross-listing o colocación privada. Ya fue Head of Global Markets de FAB desde ene-2020, por lo que conoce el negocio.','https://enterpriseam.com/uae/2025/01/16/executive-changes-at-fab-al-hilal-bank-names-new-ceo/','Verificación: Sameh Al Qubaisi renunció como Group Head of Global Markets en ene-2025 (Zawya: https://www.zawya.com/en/business/banking-and-insurance/uaes-top-lender-fab-makes-changes-to-senior-management-team-spn7hfqt ; Reuters vía Investing.com: https://investing.com/news/stock-market-news/head-of-global-markets-resigns-at-first-abu-dhabi-bank--sources-2047011), y FAB designó a Azzam Anani como responsable interino de Global Markets. No se encontró nombramiento permanente ni confirmación en 2026: verificar en LinkedIn que sigue al frente antes de escribir. Sin email verificado.'),
('Hana Al Rostamani','Group Chief Executive Officer','Dirección general','Abu Dhabi, UAE',null,null,'desconocido','influencer',3,'Anunció el stablecoin dirham con IHC y ADQ (abr-2025) y marca la agenda de activos digitales del banco; solo como referencia o con intro de tercero.','https://www.ledgerinsights.com/uaes-largest-bank-fab-to-launch-stablecoin-partnering-sovereign-investor-adq-ihc/','Demasiado senior para un primer contacto frío; usar únicamente si hay una introducción cálida.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
